import { http } from '@/shared/api/httpClient';
import type { Genre } from '@/shared/api/types';

export interface AdminTitleListItem {
  id: number;
  displayName: string;
  seasonNumber: number;
  seasonLabel?: string | null;
  posterUrl: string | null;
}

export interface CreateTitleInput {
  displayName: string;
  names: { kind: 'original' | 'english' | 'ukrainian' | 'other'; name: string }[];
  description?: string;
  /** Direct image URL (Cloudflare R2 / CDN or external). */
  posterUrl?: string | null;
  originalReleaseDate?: string | null;
  genreIds: number[];
  seasonNumber: number;
  seasonLabel?: string | null;
  status?: 'ongoing' | 'completed' | 'announced' | 'hidden';
  episodesPlanned?: { count: number | null; open: boolean };
}

export interface CreateEpisodeInput {
  number?: number | null;
  customLabel?: string | null;
  /** Direct video URL for the website (Cloudflare R2 / CDN). */
  streamUrl?: string | null;
  /** Telegram message link (t.me/<channel>/<id>) to the storage channel, for the bot. */
  videoUrl?: string | null;
  /** Telegram file_id captured from the storage channel, for the bot. */
  tgFileId?: string | null;
  /** Direct preview image URL (optional). */
  previewUrl?: string | null;
  /** Override publication timestamp (ISO 8601). Null = keep existing. */
  publishedAt?: string | null;
}

// ── Genres ───────────────────────────────────────────────
export function createGenre(name: string, slug: string): Promise<Genre> {
  return http.post<Genre>('/admin/genres', { name, slug });
}
export function deleteGenre(id: number): Promise<void> {
  return http.del(`/admin/genres/${id}`);
}

// ── Titles ───────────────────────────────────────────────
export function adminSearchTitles(q: string, limit = 20): Promise<AdminTitleListItem[]> {
  return http.get<AdminTitleListItem[]>('/admin/titles', { query: { q: q || undefined, limit } });
}
export function createTitle(input: CreateTitleInput): Promise<{ id: number }> {
  return http.post<{ id: number }>('/admin/titles', input);
}
export function updateTitle(id: number, patch: Partial<CreateTitleInput>): Promise<void> {
  return http.put(`/admin/titles/${id}`, patch);
}
export function deleteTitle(id: number): Promise<void> {
  return http.del(`/admin/titles/${id}`);
}

// ── Season grouping ──────────────────────────────────────
export function groupTitle(id: number, linkToTitleId: number): Promise<void> {
  return http.post(`/admin/titles/${id}/group`, { linkToTitleId });
}
export function ungroupTitle(id: number): Promise<void> {
  return http.del(`/admin/titles/${id}/group`);
}
export function reorderSeasons(titleId: number, order: number[]): Promise<void> {
  return http.put(`/admin/titles/${titleId}/seasons/reorder`, { order });
}

// ── Episodes ─────────────────────────────────────────────
export function createEpisode(titleId: number, input: CreateEpisodeInput): Promise<{ id: number }> {
  return http.post<{ id: number }>(`/admin/titles/${titleId}/episodes`, input);
}
export function reorderEpisodes(titleId: number, order: number[]): Promise<void> {
  return http.put(`/admin/titles/${titleId}/episodes/reorder`, { order });
}
export function updateEpisode(episodeId: number, patch: CreateEpisodeInput): Promise<void> {
  return http.put(`/admin/episodes/${episodeId}`, patch);
}
export function deleteEpisode(episodeId: number): Promise<void> {
  return http.del(`/admin/episodes/${episodeId}`);
}

export interface AdminEpisodeDetail {
  id: number;
  number: number | null;
  customLabel: string | null;
  streamUrl: string | null;
  videoUrl: string | null;
  tgFileId: string | null;
  previewUrl: string | null;
  publishedAt: string;
}

export function getAdminEpisode(episodeId: number): Promise<AdminEpisodeDetail> {
  return http.get(`/admin/episodes/${episodeId}`);
}

// ── R2 media manager ─────────────────────────────────────
export interface MediaAsset {
  id: string;
  label: string | null;
  masterUrl: string;
  segmentCount: number;
  durationS: number;
  qualities: string[];
  episodeCount: number;
  createdAt: string;
}

/** ~15 MB — safely under proxy/CDN per-request body limits (e.g. Cloudflare ~100 MB). */
const CHUNK_SIZE = 15 * 1024 * 1024;
const POLL_MS = 2000;
const MAX_WAIT_MS = 60 * 60 * 1000;

/**
 * Uploads a video in chunks (each request small enough to pass the proxy), then
 * starts async transcoding and polls `/admin/media/status` until the asset is
 * ready. `onProgress` reports the browser→server send percent (0–100); the
 * server-side transcode progress is exposed separately via the status banner.
 */
export async function uploadMedia(
  file: File,
  label: string,
  onProgress?: (percent: number) => void,
): Promise<{ id: string; label: string | null }> {
  const { uploadId } = await http.post<{ uploadId: string }>('/admin/media/upload/init');
  const total = file.size;
  const chunkCount = Math.max(1, Math.ceil(total / CHUNK_SIZE));

  for (let i = 0; i < chunkCount; i++) {
    const start = i * CHUNK_SIZE;
    const blob = file.slice(start, Math.min(start + CHUNK_SIZE, total));
    const form = new FormData();
    form.append('uploadId', uploadId);
    form.append('chunk', blob, 'chunk');
    await http.upload<void>('/admin/media/upload/chunk', form, {
      onProgress: (p) =>
        onProgress?.(Math.min(100, Math.round(((start + (blob.size * p) / 100) / total) * 100))),
    });
    onProgress?.(Math.min(100, Math.round(((start + blob.size) / total) * 100)));
  }

  const startedAt = Date.now();
  await http.post('/admin/media/upload/complete', { uploadId, label: label.trim() || undefined });

  // Transcoding runs async on the server (a long job would exceed proxy timeouts),
  // so poll the status until this upload's result/error appears.
  return new Promise((resolve, reject) => {
    const deadline = Date.now() + MAX_WAIT_MS;
    const timer = setInterval(async () => {
      if (Date.now() > deadline) {
        clearInterval(timer);
        reject(new Error('Обробка триває занадто довго'));
        return;
      }
      let status: MediaJobStatus;
      try {
        status = await getMediaStatus();
      } catch {
        return; // transient — keep polling
      }
      if (status.active) return;
      if (status.lastError && status.lastError.at >= startedAt) {
        clearInterval(timer);
        reject(new Error(status.lastError.message));
      } else if (status.lastResult && status.lastResult.at >= startedAt) {
        clearInterval(timer);
        resolve({ id: status.lastResult.id, label: status.lastResult.label });
      }
    }, POLL_MS);
  });
}

export function listMedia(): Promise<MediaAsset[]> {
  return http.get<MediaAsset[]>('/admin/media');
}

export function deleteMedia(id: string): Promise<void> {
  return http.del(`/admin/media/${id}`);
}

export interface MediaJobStatus {
  active: boolean;
  label: string | null;
  phase: 'transcoding' | 'uploading' | 'finalizing';
  percent: number;
  uploadedSegments: number;
  totalSegments: number;
  startedAt: number | null;
  lastResult: { id: string; label: string | null; at: number } | null;
  lastError: { message: string; at: number } | null;
}

/** Live status of the single running ingest job (shared across admins). */
export function getMediaStatus(): Promise<MediaJobStatus> {
  return http.get<MediaJobStatus>('/admin/media/status');
}

export interface PhotoAsset {
  id: string;
  key: string;
  url: string;
  label: string | null;
  createdAt: string;
}

export function uploadPhoto(
  file: File | Blob,
  label: string,
  onProgress?: (percent: number) => void,
): Promise<PhotoAsset> {
  const form = new FormData();
  form.append('file', file, file instanceof File ? file.name : 'pasted_image.png');
  if (label.trim()) form.append('label', label.trim());
  return http.upload<PhotoAsset>('/admin/photos', form, { onProgress });
}

export function listPhotos(): Promise<PhotoAsset[]> {
  return http.get<PhotoAsset[]>('/admin/photos');
}

export function deletePhoto(id: string): Promise<void> {
  return http.del(`/admin/photos/${id}`);
}
